entry.summary:
/* ------------------------------------------------------------- ONE BLOCK → ALL 56 tables with correct counts Works even on the most restrictive old ASE servers ------------------------------------------------------------- */
set nocount on go
/* Use the safe maximum size – 8000 works everywhere */ declare @sql varchar(8000) select @sql = ''
/* Build the query – we use CHAR(10) for line breaks so it never truncates */ select @sql = @sql + 'select ''' + o.name + ''' as table_name, count(*) from ' + db_name() + '..' + o.name + ' where INTERNTIMESTAMP >= dateadd(day,-10045,getdate())' + char(10) + 'union all ' + char(10) from sysobjects o where o.type = 'U' and exists (select 1 from syscolumns c where c.id = o.id and c.name = 'INTERNTIMESTAMP') order by o.name
/* Remove the final 'union all ' + line breaks */ if len(@sql) > 20 select @sql = substring(@sql, 1, len(@sql) - 20) -- removes last 20 chars safely else select @sql = 'select ''No tables found'' as table_name, 0'
/* Optional: see the full generated SQL (uncomment if needed) */ -- print @sql
/* Execute it */ exec (@sql) go

/* ------------------------------------------------------------- ONE SINGLE EXECUTION – works in DBVisualizer / isql / any tool Shows rows from last 45 days for every table that has INTERNTIMESTAMP ------------------------------------------------------------- */
declare @sql nvarchar(8000) -- use nvarchar if your ASE supports it (15.7+) -- or varchar(8000) on very old versions
select @sql = ''
/* Build the big UNION ALL query */ select @sql = @sql + 'select ''' + o.name + ''' as table_name, count(*) as rows_last_45_days from ' + o.name + ' where INTERNTIMESTAMP >= dateadd(day, -45, getdate()) union all ' from sysobjects o where o.type = 'U' and exists (select 1 from syscolumns c where c.id = o.id and c.name = 'INTERNTIMESTAMP') order by o.name
/* Safely remove the trailing ' union all ' – no negative length */ if len(@sql) > 11 select @sql = left(@sql, len(@sql) - 11) -- removes last 11 chars else select @sql = 'select ''No tables found'' as table_name, 0 as rows_last_45_days'
/* Execute it */ exec(@sql) go
